const stok = { kopi: 5, roti: 2 };
function cekStok(nama, qty, callback) {
  setTimeout(() => {
    if (qty > stok[nama]) callback(new Error(`Stok ${nama} tidak cukup`));
    else callback(null, stok[nama] - qty);
  }, 100);
}
const tampil = (err, sisa) => {
  if (err) return console.log("Gagal:", err.message);
  console.log("Sisa stok:", sisa);
};
cekStok("kopi", 3, tampil);
cekStok("roti", 4, tampil);
